1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	
14	import java.time.LocalDate;
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public abstract class OwnerMapper {
23	
24	    /**
25	     * More than this many owners already sharing a {@code registrationDate} raises the
26	     * {@code bulkSignupWarning} on responses for that day.
27	     */
28	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
29	
30	    @Autowired
31	    protected OwnerRepository ownerRepository;
32	
33	    @Mapping(target = "displayName",
34	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
35	    @Mapping(target = "initials",
36	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
37	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
38	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
39	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
40	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
41	    @Mapping(target = "locality", expression = "java(locality(owner))")
42	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
43	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
44	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
45	    @Mapping(target = "identityKey",
46	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner))")
47	    @Mapping(target = "telephoneDisplay",
48	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.Telephones.toDisplay(owner.getTelephone()))")
49	    public abstract OwnerDto toOwnerDto(Owner owner);
50	
51	    /**
52	     * The owner's {@code membershipPoints}: the raw loyalty score (see
53	     * {@link org.springframework.samples.petclinic.rest.function.owner.Memberships}), built from a
54	     * present email, no namesakes, a household of 3 or more and tenure over 365 days.
55	     */
56	    protected int membershipPoints(Owner owner) {
57	        long householdSize = org.springframework.samples.petclinic.rest.function.owner.Households
58	                .size(owner, ownerRepository);
59	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
60	                .membershipPoints(owner, householdSize);
61	    }
62	
63	    /**
64	     * The owner's {@code membershipLevel}: the grade {@code membershipPoints} buckets into — 1 for
65	     * 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
66	     */
67	    protected int membershipLevel(Owner owner) {
68	        return org.springframework.samples.petclinic.rest.function.owner.Memberships
69	                .membershipLevel(membershipPoints(owner));
70	    }
71	
72	    /**
73	     * The owner's preferred contact channel: {@code EMAIL} when an email address is
74	     * present (non-null and non-blank), otherwise {@code PHONE}.
75	     */
76	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
77	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
78	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
79	    }
80	
81	    /** The age (in years) at which an owner stops being a minor and becomes an adult. */
82	    private static final int ADULT_AGE = 18;
83	
84	    /** The age (in years) at which an owner becomes a senior. */
85	    private static final int SENIOR_AGE = 65;
86	
87	    /**
88	     * Derives the owner's {@code ageBand} from {@code birthDate} as of the
89	     * {@code registrationDate}: {@code MINOR} when under {@value #ADULT_AGE},
90	     * {@code ADULT} when {@value #ADULT_AGE} to {@value #SENIOR_AGE}-1, and
91	     * {@code SENIOR} when {@value #SENIOR_AGE} or older. Returns {@code null} when
92	     * either the birth date or the registration date is absent, so an owner created
93	     * without a birth date has no age band.
94	     */
95	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
96	        LocalDate birthDate = owner.getBirthDate();
97	        LocalDate registrationDate = owner.getRegistrationDate();
98	        if (birthDate == null || registrationDate == null) {
99	            return null;
100	        }
101	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
102	        if (age < ADULT_AGE) {
103	            return OwnerDto.AgeBandEnum.MINOR;
104	        }
105	        if (age < SENIOR_AGE) {
106	            return OwnerDto.AgeBandEnum.ADULT;
107	        }
108	        return OwnerDto.AgeBandEnum.SENIOR;
109	    }
110	
111	    /**
112	     * Derives the owner's {@code locality} (canonical region string) from the
113	     * region-and-hash identity: the REGION segment of the {@code customerCode} (everything
114	     * before the first {@code '-'}). Legacy owners with no customer code (e.g. seed data)
115	     * fall back to deriving the region directly from postcode, then city, then
116	     * {@code "UNKNOWN"}.
117	     */
118	    protected String locality(Owner owner) {
119	        String region = org.springframework.samples.petclinic.rest.function.owner.CustomerCodes
120	                .regionOf(owner.getCustomerCode());
121	        if (region != null) {
122	            return region;
123	        }
124	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCodes.region(owner);
125	    }
126	
127	    /**
128	     * Builds the membership number '<customerCode>-M<YY>', where YY is the last two digits of
129	     * the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Returns {@code null} when either the
130	     * customer code or the registration date is absent (e.g. legacy seed owners).
131	     */
132	    protected String membershipNumber(Owner owner) {
133	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
134	            return null;
135	        }
136	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
137	    }
138	
139	    /**
140	     * True when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} other owners have already
141	     * been created for this owner's {@code registrationDate}, using the same per-day
142	     * accumulation the daily create limit enforces (the owner itself is excluded). Returns
143	     * {@code false} when the owner has no registration date (e.g. legacy seed owners).
144	     */
145	    protected boolean bulkSignupWarning(Owner owner) {
146	        LocalDate registrationDate = owner.getRegistrationDate();
147	        if (registrationDate == null) {
148	            return false;
149	        }
150	        long count = ownerRepository.findAll().stream()
151	                .filter(existing -> !existing.getId().equals(owner.getId()))
152	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
153	                .count();
154	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
155	    }
156	
157	    /**
158	     * The Luhn check digit (0-9) computed over the digits contained in the owner's
159	     * {@code customerCode}. Returns {@code null} when the customer code is absent (e.g.
160	     * legacy seed owners).
161	     */
162	    protected Integer checkDigit(Owner owner) {
163	        String customerCode = owner.getCustomerCode();
164	        if (customerCode == null) {
165	            return null;
166	        }
167	        int sum = 0;
168	        boolean dbl = true;
169	        for (int i = customerCode.length() - 1; i >= 0; i--) {
170	            char c = customerCode.charAt(i);
171	            if (c < '0' || c > '9') {
172	                continue;
173	            }
174	            int d = c - '0';
175	            if (dbl) {
176	                d *= 2;
177	                if (d > 9) {
178	                    d -= 9;
179	                }
180	            }
181	            sum += d;
182	            dbl = !dbl;
183	        }
184	        return (10 - (sum % 10)) % 10;
185	    }
186	
187	    public abstract Owner toOwner(OwnerDto ownerDto);
188	
189	    @Mapping(target = "id", ignore = true)
190	    @Mapping(target = "pets", ignore = true)
191	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
192	
193	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
194	
195	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
196	
197	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
198	        OwnerPageDto ownerPageDto = new OwnerPageDto();
199	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
200	        ownerPageDto.setPage(ownerPage.getNumber());
201	        ownerPageDto.setSize(ownerPage.getSize());
202	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
203	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
204	        return ownerPageDto;
205	    }
206	}
